window.ScripturaLexicons.BDAG_PART_0217 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0217-01\" data-source=\"BDAG\" data-search=\"λειποτακτέω verbo desertar; afastar-se BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λειποτακτέω</td><td>verbo</td><td>desertar; afastar-se</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0217-02\" data-source=\"BDAG\" data-search=\"λείπω verbo faltar; carecer; ficar aquém BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λείπω</td><td>verbo</td><td>faltar; carecer; ficar aquém</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0217-03\" data-source=\"BDAG\" data-search=\"λειτουργέω verbo prestar serviço; exercer funções cultuais BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λειτουργέω</td><td>verbo</td><td>prestar serviço; exercer funções cultuais</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0217-04\" data-source=\"BDAG\" data-search=\"λειτουργία, ας, ἡ substantivo feminino serviço público; culto; assistência BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λειτουργία, ας, ἡ</td><td>substantivo feminino</td><td>serviço público; culto; assistência</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0217-05\" data-source=\"BDAG\" data-search=\"λειτουργικός, ή, όν adjetivo dedicado a serviço especial BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λειτουργικός, ή, όν</td><td>adjetivo</td><td>dedicado a serviço especial</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0217-06\" data-source=\"BDAG\" data-search=\"λειτουργός, οῦ, ὁ substantivo masculino servidor; ministro; auxiliar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λειτουργός, οῦ, ὁ</td><td>substantivo masculino</td><td>servidor; ministro; auxiliar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0217-07\" data-source=\"BDAG\" data-search=\"λείχω verbo lamber BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λείχω</td><td>verbo</td><td>lamber</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0217-08\" data-source=\"BDAG\" data-search=\"Λέκτρα, ας, ἡ nome próprio feminino Lectra BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Λέκτρα, ας, ἡ</td><td>nome próprio feminino</td><td>Lectra</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0217-09\" data-source=\"BDAG\" data-search=\"λεμά partícula interrogativa por quê? BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λεμά</td><td>partícula interrogativa</td><td>por quê?</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0217-10\" data-source=\"BDAG\" data-search=\"λέντιον, ου, τό substantivo neutro pano de linho; toalha BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λέντιον, ου, τό</td><td>substantivo neutro</td><td>pano de linho; toalha</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0217-11\" data-source=\"BDAG\" data-search=\"λεόπαρδος, ου, ὁ substantivo masculino leopardo; soldado brutal BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λεόπαρδος, ου, ὁ</td><td>substantivo masculino</td><td>leopardo; soldado brutal</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0217-12\" data-source=\"BDAG\" data-search=\"λεπίς, ίδος, ἡ substantivo feminino escama; película fina BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λεπίς, ίδος, ἡ</td><td>substantivo feminino</td><td>escama; película fina</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0217-13\" data-source=\"BDAG\" data-search=\"λέπρα, ας, ἡ substantivo feminino doença cutânea grave; possível hanseníase BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λέπρα, ας, ἡ</td><td>substantivo feminino</td><td>doença cutânea grave; possível hanseníase</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0217-14\" data-source=\"BDAG\" data-search=\"λεπράω verbo sofrer de doença da pele BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λεπράω</td><td>verbo</td><td>sofrer de doença da pele</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0217-15\" data-source=\"BDAG\" data-search=\"λεπρός, ά, όν adjetivo portador de doença cutânea grave BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λεπρός, ά, όν</td><td>adjetivo</td><td>portador de doença cutânea grave</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0217-16\" data-source=\"BDAG\" data-search=\"λεπτός, ή, όν adjetivo pequeno; fino; moeda de cobre BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λεπτός, ή, όν</td><td>adjetivo</td><td>pequeno; fino; moeda de cobre</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0217-17\" data-source=\"BDAG\" data-search=\"Λευί, ὁ nome próprio masculino Levi; nome bíblico BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Λευί, ὁ</td><td>nome próprio masculino</td><td>Levi; nome bíblico</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0217-18\" data-source=\"BDAG\" data-search=\"Λευίτης, ου, ὁ substantivo masculino levita BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Λευίτης, ου, ὁ</td><td>substantivo masculino</td><td>levita</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0217-19\" data-source=\"BDAG\" data-search=\"Λευιτικός, ή, όν adjetivo levítico BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Λευιτικός, ή, όν</td><td>adjetivo</td><td>levítico</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0217-20\" data-source=\"BDAG\" data-search=\"λευκαίνω verbo tornar branco; branquear BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">λευκαίνω</td><td>verbo</td><td>tornar branco; branquear</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0217-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λειποτακτέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λειποτακτέω</span> ou <span class=\"greek\">λιποτακτέω</span> (veja <span class=\"greek\">λείπω</span>, <span class=\"greek\">τάξις</span>; termo técnico militar «abandonar as fileiras, desertar»; Plut., Mor. 241a; Polemo, Decl. 2, 44 p. 31, 17; PLips 45, 18; 46, 15; PLond III, 1247, 14 p. 225 [IV d.C.]; 4 Macc 9:23) em sentido figurado, afastar-se <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span>, de alguma coisa <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θελήματος</span> (<span class=\"greek\">θεοῦ</span>) 1 Cl 21:4 (cf. Philo, Gig. 43 [268] <span class=\"greek\">καλὸν</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">λιποτακτῆσαι</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">τάξεως</span>).—DELG s.v. <span class=\"greek\">τάσσω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0217-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λείπω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λείπω</span> futuro, 3ª pessoa do singular <span class=\"greek\">λείψει</span> ApcEsdr; 2º aoristo <span class=\"greek\">ἔλιπον</span>, subjuntivo, 3ª pessoa do singular <span class=\"greek\">λίπῃ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:13</a> variante textual; particípio perfeito passivo <span class=\"greek\">λελειμμένος</span> 2 Macc 4:45 (Hom.+, «deixar [para trás]» e outros sentidos).</p><p class=\"entry-text\">① deixar para trás, uso transitivo, médio e passivo</p><p class=\"entry-text\">ⓐ ficar aquém, ser inferior, carecer (Hdt. 7, 8, 1; Diod S 17, 46, 1; Jos., Bell. 3, 482, Ant. 14, 474; Just., A I, 67, 1 e 6) <span class=\"greek\">ἔν</span> <span class=\"greek\">τινι</span> em alguma coisa (Sb 620, 6 [97/96 a.C.] a respeito de um templo <span class=\"greek\">λείπεσθαι</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">ἄσυλον</span>; SIG 618, 15; 800, 29; PGM 4, 2347) <span class=\"greek\">ἐν</span> <span class=\"greek\">μηδενί</span> não carecer de coisa alguma <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:4</a>.</p><p class=\"entry-text\">ⓑ estar sem algo, carecer, necessitar (de), com genitivo (B-D-F §180, 4; cf. Soph., El. 474; Ps.-Pla., Axioch. 366d; posteriormente, por exemplo Libanius, Progym.: Confirm. 1, 1 vol. VIII p. 138f. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐνθέου</span> <span class=\"greek\">μανίας</span>) <span class=\"greek\">σοφίας</span> carecer de sabedoria <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">Js 1:5</a>. <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐφημέρου</span> <span class=\"greek\">τροφῆς</span> necessitar do alimento cotidiano 2:15. <span class=\"greek\">θεοῦ</span> carecer de Deus ITr 5:2b. <span class=\"greek\">μηδενός</span> não carecer de nada IPol 2:2.</p><p class=\"entry-text\">② carecer de algo que, por algum motivo, deveria estar presente; uso intransitivo, voz ativa (<span class=\"greek\">λείπει</span> <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span>: Polyb. 10, 18, 8; Epict. 2, 14, 19; Jos., Ant. 12, 36; <span class=\"greek\">λείπει</span> <span class=\"greek\">τίς</span> <span class=\"greek\">τινι</span> ApcEsdr 6:18 p. 31, 27 Tdf.) <span class=\"greek\">σοὶ</span> <span class=\"greek\">πολλὰ</span> <span class=\"greek\">λείπει</span> falta-te muito Hv 3, 1, 9. <span class=\"greek\">πολλὰ</span> <span class=\"greek\">ἡμῖν</span> <span class=\"greek\">λείπει</span> falta-nos muito ITr 5:2a. <span class=\"greek\">ἔτι</span> <span class=\"greek\">ἕν</span> <span class=\"greek\">σοι</span> <span class=\"greek\">λείπει</span> ainda te falta uma coisa <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:22</a> (cf. Jos., Bell. 4, 257 <span class=\"greek\">τοῖς</span> <span class=\"greek\">τολμήμασιν</span> <span class=\"greek\">ἓν</span> <span class=\"greek\">μόνον</span> <span class=\"greek\">λείπει</span>; TestAbr A 14 p. 93, 26f [Stone p. 34] <span class=\"greek\">τί</span> <span class=\"greek\">ἔτι</span> <span class=\"greek\">λείπεται</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ψυχῇ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σώζεσθαι</span>;) <span class=\"greek\">ἵνα</span> <span class=\"greek\">μηδὲν</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">λείπῃ</span> para que nada lhes falte <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 3:13</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">λείποντα</span> (Just., A I, 52, 2; <span class=\"greek\">τὰ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">ψαλμοῦ</span> Just., D 106, 1; Lucian, Syr. Dea 26) aquilo que falta, as deficiências 1:5. Seguido de infinitivo (cf. B-D-F §393, 4) <span class=\"greek\">λείπει</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">πύργῳ</span> <span class=\"greek\">ἔτι</span> <span class=\"greek\">μικρὸν</span> <span class=\"greek\">οἰκοδομηθῆναι</span> a torre ainda precisa de um pouco para ser concluída, ainda não está inteiramente terminada Hs 9, 9, 4.—B. 839. DELG. M-M. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0217-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λειτουργέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λειτουργέω</span> imperfeito <span class=\"greek\">ἐλειτούργουν</span>; futuro <span class=\"greek\">λειτουργήσω</span> LXX; 1º aoristo <span class=\"greek\">ἐλειτούργησα</span> (cf. ático <span class=\"greek\">λεώς</span> = <span class=\"greek\">λαός</span>, veja esse verbete, + <span class=\"greek\">ἐργον</span>; X.+; ins, pap, LXX; TestSol 12:6 v.l.; TestLevi 3:5, TestAsh 2:2; EpArist, Philo, Joseph.; sobre a grafia, veja Mayser 127; Mlt-H. 76f) em sentido geral, «prestar um serviço público, exercer um cargo público» (no mundo greco-romano, esperava-se que os cidadãos de destaque exercessem diversos cargos, inclusive, especialmente, o de sumo sacerdote, arcando com todos os custos do exercício, ou assumissem os custos de construir ou manter edifícios públicos e de produzir espetáculos teatrais e jogos; por esses serviços, seriam reconhecidos como pessoas de mérito extraordinário [s. <span class=\"greek\">ἀρετή</span>] ou benfeitores [s. <span class=\"greek\">εὐεργέτης</span>]; mas a palavra também designa atividades menos prestigiosas SEG XXVI, 1392, 31 fornecer carroças e mulas; New Docs 1, 42–44) na literatura aqui considerada, quase exclusivamente de serviços religiosos e rituais, tanto em sentido amplo como restrito (SIG 717, 23f [100 a.C.] <span class=\"greek\">ἐλειτούργησαν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἱερῷ</span> <span class=\"greek\">εὐτάκτως</span>; 736, 73; 74f <span class=\"greek\">λειτουργούντω</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">θεοῖς</span>; 97f [92 a.C.]; PLond I, 33a, 3 p. 19 [II a.C.]; 41 B, 1; UPZ 42, 2 [162 a.C.]; 47, 3; BGU 1006, 10; LXX; EpArist 87; Dssm., B 137 [BS 140f]; Anz 346f; Danker, Benefactor [literatura]). Pelo emprego desse termo, os escritores do Novo Testamento conferem uma aura de elevada condição a quem presta qualquer tipo de serviço.</p><p class=\"entry-text\">① prestar serviço formal especial, servir, exercer funções de responsabilidade cultual ou ritual</p><p class=\"entry-text\">ⓐ de sacerdotes e levitas no templo de Deus (cf. Ex 28:35, 43; 29:30; Num 18:2; Sir 4:14; 45:15; Jdth 4:14; 1 Macc 10:42; Philo, Mos. 2, 152; Jos., Bell. 2, 409, Ant. 20, 218) em uso absoluto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:11</a>. <span class=\"greek\">λ</span>. <span class=\"greek\">τῷ</span> <span class=\"greek\">θυσιαστηρίῳ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> prestar serviços no altar de Deus 1 Cl 32:2 (cf. Jo 1:9, 13); (com <span class=\"greek\">ἱερατεύειν</span>, como em Sir 45:15) <span class=\"greek\">λ</span>. <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> 43:4; GJs 4:1 (1 Km 3:1).—Quanto a serviços cristãos <span class=\"greek\">ἐν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θυσιαστηρίῳ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">τὸ</span> <span class=\"greek\">θεῖον</span> prestar serviço a Deus junto ao altar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/TIT.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">Tit 1:9</a> v.l.—Quanto aos responsáveis pelas congregações cristãs: <span class=\"greek\">λ</span>. <span class=\"greek\">ἁμέμπτως</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ποιμνίῳ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Χριστοῦ</span> servir irrepreensivelmente ao rebanho de Cristo 1 Cl 44:3. Quanto aos supervisores Hs 9, 27, 3. Quanto aos supervisores e servidores <span class=\"greek\">λ</span>. <span class=\"greek\">τὴν</span> <span class=\"greek\">λειτουργίαν</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">προφητῶν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">διδασκάλων</span> desempenhar o serviço de profetas e mestres D 15:1 (veja b, abaixo, quanto a <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:2</a>.—<span class=\"greek\">λειτ</span>. <span class=\"greek\">λ</span>. Demosth. 21, 154; frequentemente na LXX; também Philo, Spec. Leg. 1, 82; SIG 409, 61).—Quanto aos anjos (TestLevi 3:5) <span class=\"greek\">τῷ</span> <span class=\"greek\">θελήματι</span> <span class=\"greek\">αὐτοῦ</span> (entenda-se <span class=\"greek\">θεοῦ</span>) <span class=\"greek\">λειτουργοῦσιν</span> <span class=\"greek\">παρεστῶτες</span> permanecem junto de (Deus) e servem à vontade (de Deus) 1 Cl 34:5; cf. v. 6 (Da 7:10 Theod.).</p><p class=\"entry-text\">ⓑ de outras manifestações de devoção religiosa (Dionys. Hal. 2, 22, 2 <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἱερῶν</span> das esposas dos sacerdotes e de seus filhos, que realizam determinados ritos não permitidos aos homens) incluindo a oração (com <span class=\"greek\">νηστεύειν</span> e em referência aos profetas e mestres) <span class=\"greek\">τ</span>. <span class=\"greek\">κυρίῳ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:2</a>. <span class=\"greek\">λ</span>. <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span> (cf. Jo 1:13b) Hm 5, 1, 2; cf. 3; Hs 7:6. Quanto aos justos do Antigo Testamento <span class=\"greek\">οἱ</span> <span class=\"greek\">τελείως</span> <span class=\"greek\">λειτουργήσαντες</span> aqueles que prestaram serviço excelente a Deus 1 Cl 9:2.</p><p class=\"entry-text\">② conferir um benefício material especial, servir (X., Mem. 2, 7, 6; Chares Hist.: 125 Fgm. 4 p. 659, 28 Jac. [em Athen. 12, 54, 538e]; <span class=\"greek\">τῷ</span> <span class=\"greek\">βίῳ</span> <span class=\"greek\">λ</span>. Orig., C. Cels. 8, 57, 1 e 6) <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">σαρκικοῖς</span> <span class=\"greek\">λ</span>. prestar um serviço em bens materiais <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:27</a>—Sobre este artigo e o seguinte, veja Elbogen 5; 511; FOertel, D. Liturgie, 1917; NLewis, Inventory of Compulsory Services in Ptolemaic and Roman Egypt ’68; WBrandt, D. Wortgruppe <span class=\"greek\">λειτουργεῖν</span> im Hb u. 1 Kl: Jahrb. d. Theol. Schule Bethel 1, 1930, 145–76; OCasel, <span class=\"greek\">λειτουργία</span>—munus: Oriens Christ. III 7, ’32, 289–302; EPeterson, Nuntius 2, ’49, 10f; ARomeo, Miscellanea Liturgica (LMohlberg Festschr.), vol. 2, ’49, 467–519; FDanker, Gingrich Festschr. ’72, 108ff.—Veja <span class=\"greek\">λειτουργία</span>, <span class=\"greek\">λειτουργικός</span>, <span class=\"greek\">λειτουργός</span>.—DELG s.v. <span class=\"greek\">λαός</span>. M-M. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0217-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λειτουργία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λειτουργία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (veja o artigo anterior; Pla.+; ins, pap, LXX, ParJer 3; ApcSed 14, 3 e 11; EpArist, Philo, Joseph., empréstimo na literatura rabínica) originalmente «serviço público», designação usual de um serviço prestado por um indivíduo ao Estado ou ao culto público (frequentemente sem remuneração; veja a bibliografia em <span class=\"greek\">λειτουργέω</span> 2), na literatura aqui examinada, quase sempre empregado com alguma conotação religiosa. Assim como no uso do verbo <span class=\"greek\">λειτουργέω</span>, os escritores do Novo Testamento sugerem uma aura de elevada posição para quem presta qualquer tipo de serviço.</p><p class=\"entry-text\">① serviço de natureza formal ou pública, prestação de serviço</p><p class=\"entry-text\">ⓐ quanto aos serviços rituais e cultuais (Diod S 1, 21, 7; SIG 1109, 111; UPZ 17, 17 [163 a.C.] <span class=\"greek\">λ</span>. <span class=\"greek\">τῷ</span> <span class=\"greek\">θεῷ</span>; 40, 19 [161 a.C.]; PTebt 302, 30 [veja Dssm. B 138=BS 141]; Ex 37:19; Num 8:22; 16:9; 18:4; 2 Ch 31:2; EpArist; Philo, Virt. 54 al.; Jos., Bell. 1, 26, Ant. 3, 107 al.; Hippol., Ref. 9, 30, 4) serviço sacerdotal <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:23</a>. <span class=\"greek\">τὰς</span> <span class=\"greek\">προσφορὰς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">λειτουργίας</span> <span class=\"greek\">ἐπιτελεῖσθαι</span> apresentar ofertas e realizar (outros) serviços cerimoniais 1 Cl 40:2. <span class=\"greek\">τὰ</span> <span class=\"greek\">σκεύη</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">λ</span>. os utensílios empregados no serviço sacerdotal <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.21\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9:21</a> (ParJer 3:9, 11, 18). Quanto ao serviço do sumo sacerdote 1 Cl 40:5. Figuradamente, quanto ao ofício sumo sacerdotal de Cristo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:6</a>.</p><p class=\"entry-text\">ⓑ de outras espécies de serviço a Deus 1 Cl 20:10. Quanto a Noé 1 Cl 9:4. Quanto a Paulo (com <span class=\"greek\">θυσία</span>, veja esse verbete, acepção 1; cf. BGU 1201, 7 [2 d.C.] <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">λιτουργείας</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">θυσείας</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">θεῶν</span>) serviço sacrificial <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.17\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:17</a>.—Quanto aos responsáveis pelas congregações cristãs (<span class=\"greek\">ἡ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἐπισκοπῆς</span> <span class=\"greek\">λ</span>. Iren. 3, 3, 3 [Harv. II 10, 3]) <span class=\"greek\">διαδέχεσθαι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">λ</span>. <span class=\"greek\">αὐτῶν</span> suceder-lhes no ofício 1 Cl 44:2; <span class=\"greek\">ἡ</span> <span class=\"greek\">αὐτοῖς</span> <span class=\"greek\">τετιμημένη</span> <span class=\"greek\">λ</span>. o ofício que eles exerciam honrosamente 44:6; <span class=\"greek\">ἀποβάλλεσθαι</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">λ</span>. ser destituído do ofício 44:3. Sobre D 15:1, cf. <span class=\"greek\">λειτουργέω</span> 1a.—Também quanto às atividades de uma pessoa sem cargo oficial no serviço da igreja <span class=\"greek\">μὴ</span> <span class=\"greek\">παρεκβαίνειν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ὡρισμένον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">λ</span>. <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">κανόνα</span> não ultrapassar os limites estabelecidos de seu serviço 1 Cl 41:1. Quanto aos atos que manifestam caridade cristã e outras virtudes para além do cumprimento do dever comum e que, por isso, se assemelham aos serviços de cidadãos dedicados ao bem público, evocando assim especial aprovação divina: <span class=\"greek\">αἱ</span> <span class=\"greek\">λ</span>. <span class=\"greek\">αὗται</span> estes serviços Hs 5, 3, 3; cf. 5, 3, 8 (<span class=\"greek\">λ</span>. <span class=\"greek\">ἐκκλησίας</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">σωτηρίᾳ</span> <span class=\"greek\">ἀνθρώπων</span> Orig., C. Cels. 8, 75, 18).—Quanto aos anjos: <span class=\"greek\">λ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">κτίσεως</span> «serviço à criação» Hippol., Ref. 9, 30, 2.</p><p class=\"entry-text\">② serviço de natureza pessoal, ajuda, assistência, serviço em sentido figurado derivado do significado principal e da acepção 1: quanto aos serviços prestados por Epafrodito a Paulo <span class=\"greek\">ἵνα</span> <span class=\"greek\">ἀναπληρώσῃ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ὑστέρημα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πρός</span> <span class=\"greek\">με</span> <span class=\"greek\">λειτουργίας</span> para que suprisse aquilo que faltava em vosso serviço para comigo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.30\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:30</a>. Com referência à coleta <span class=\"greek\">ἡ</span> <span class=\"greek\">διακονία</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">λ</span>. <span class=\"greek\">ταύτης</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.9.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 9:12</a>.—ESchweizer, D. Leben d. Herrn in d. Gemeinde u. ihren Diensten, ’46, 19–23; AHillorst, Filología Neotestamentaria 1, ’88, 27–34.—DELG s.v. <span class=\"greek\">λαός</span>. M-M. EDNT. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0217-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λειτουργικός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λειτουργικός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (PPetr II, 39 [e] [6 ocorrências]; veja Dssm., B 138=BS 141]; PTebt 5, 49 [118 a.C.]; 102, 3. Mas também em sentido ritual PTebt 88, 3 [115/114 a.C.] <span class=\"greek\">ἡμέραι</span> <span class=\"greek\">λειτουργικαί</span>=os dias em que os profetas do templo têm permissão de realizar determinados atos sagrados [Mitt-Wilck. I/2, p. 94; WOtto, Priester u. Tempel im hellenist. Ägypt. II 1908 p. 33, 2; 39, 2]; igualmente Mitt-Wilck. I /2, 115, 15; 146; Ex 31:10; 39:12; Num 4:12, 26; 2 Ch 24:14) dedicado a serviço especial, dito dos anjos <span class=\"greek\">λ</span>. <span class=\"greek\">πνεύματα</span> espíritos dedicados a um serviço especial (a Deus) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:14</a> (cf. Philo, Virt. 74 <span class=\"greek\">ἄγγελοι</span> <span class=\"greek\">λειτουργοί</span>).—Veja <span class=\"greek\">λειτουργέω</span>, <span class=\"greek\">λειτουργία</span>, <span class=\"greek\">λειτουργός</span>.—DELG s.v. <span class=\"greek\">λαός</span>. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0217-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λειτουργός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λειτουργός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (veja <span class=\"greek\">λειτουργέω</span>; Polyb. e outros; pap, LXX; pseudepigr.; Ath. 10:3) originalmente «aquele que presta serviço público», na literatura aqui considerada (exceto TestAsh 2:2), sempre com conotações sagradas (<span class=\"greek\">λ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">θεῶν</span> Dionys. Hal. 2, 2, 3; 2, 73, 2; Plut., Mor. 417a; ins [século I a.C.: REA 32, 1930, p. 5] <span class=\"greek\">θεοῖς</span> <span class=\"greek\">λιτουργοί</span>; inscrição procedente de Mileto: GKawerau e ARehm, D. Delphinion in M. 1914, 396; LXX; TestSol 4:13 D; TestAbr A 15 p. 95, 5 [Stone p. 38]; TestLevi; EpArist 95; Philo; Hippol., Ref. 10, 9, 1 <span class=\"greek\">τοῦ</span> <span class=\"greek\">ὄφεως</span> <span class=\"greek\">λ</span>.).</p><p class=\"entry-text\">① aquele que exerce serviço administrativo ou cultual, servidor, ministro, sentido formal</p><p class=\"entry-text\">ⓐ de autoridades greco-romanas <span class=\"greek\">λ</span>. <span class=\"greek\">θεοῦ</span> servidores de Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:6</a> (veja AvanVeldhuizen, Wie zijn <span class=\"greek\">λειτουργοὶ</span> <span class=\"greek\">θεοῦ</span> in <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:6</a>: TSt 32, 1914, 302–11). Quanto aos seres celestiais como servidores de Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:7</a>; 1 Cl 36:3 (ambos Ps 103:4; cf. 102:21; Philo, Virt. 74 <span class=\"greek\">ἄγγελοι</span> <span class=\"greek\">λειτουργοί</span>).</p><p class=\"entry-text\">ⓑ de sacerdotes 1 Cl 41:2; GJs 23:1. Quanto a Cristo, o verdadeiro sumo sacerdote <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁγίων</span> <span class=\"greek\">λ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">σκηνῆς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ἀληθινῆς</span> ministro no santuário e no verdadeiro tabernáculo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 8:2</a> (Philo, Leg. All. 3, 135 <span class=\"greek\">λειτουργὸς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἁγίων</span>).—Também quanto aos profetas <span class=\"greek\">οἱ</span> <span class=\"greek\">λειτουργοὶ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">χάριτος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> 1 Cl 8:1. Quanto a Paulo, apóstolo das nações/gentios, <span class=\"greek\">λ</span>. <span class=\"greek\">Χριστοῦ</span> <span class=\"greek\">Ἰησοῦ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἔθνη</span> ministro de Cristo Jesus para os gentios <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.16\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 15:16</a>. O termo <span class=\"greek\">φιλοτιμέομαι</span> no contexto imediato (v. 20) é frequentemente usado em referência ao serviço prestado por cidadãos dedicados ao bem público (veja o verbete).</p><p class=\"entry-text\">② aquele que presta serviço pessoal, auxiliar, ajudante; sentido figurado de 1, elevando assim a condição da pessoa designada: quanto a Epafrodito <span class=\"greek\">λειτουργὸς</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">χρείας</span> <span class=\"greek\">μου</span> aquele que atendeu às minhas necessidades (=meu auxiliar) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 2:25</a>.—DELG s.v. <span class=\"greek\">λαό</span>. M-M. TW. Spicq. Veja bibliografia no verbete <span class=\"greek\">λειτουργέω</span> 2.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0217-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λείχω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λείχω</span> futuro, 3ª pessoa do plural <span class=\"greek\">λείξουσιν</span>; aoristo <span class=\"greek\">ἔλειξαν</span> LXX (Aeschyl., Hdt.+; LXX) lamber <span class=\"greek\">τὶ</span>, algo, dito de cães (3 Km 20:19) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.21\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:21</a> variante textual. B. 267.—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0217-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λέκτρα, ας, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Λέκτρα</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> Lectra, esposa de Onesíforo AcPl Ant 13, 7f (cf. Aa 1, 236, 7) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.19\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:19</a> variante textual que a apresenta como esposa de Áquila (veja Dibelius, Hdb. ad loc.).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0217-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λεμά</h1><div class=\"entry-meta\"><span>partícula interrogativa</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λεμά</span> (aramaico <span class=\"hebrew\" dir=\"rtl\">לְמָא</span>) por quê? <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.46\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:46</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:34</a> (Ps 22:2); (variantes textuais <span class=\"greek\">λαμά</span>, <span class=\"greek\">λιμά</span>) veja <span class=\"greek\">λαμά</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0217-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λέντιον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λέντιον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (empréstimo do latim linteum, também na literatura rabínica; Peripl. Eryth. c. 6; Arrian, Peripl. 4; IMagnMai 116, 34; POxy 929, 10 <span class=\"greek\">λίνον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">λέντιον</span>; Ostraka II 1611, 1; Hahn 235; 262; 266; GrBar 3:5) pano de linho Hv 3, 1, 4; toalha <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.4\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:4f</a> (Vi. Aesopi I c. 61 de uma mulher que está se preparando para lavar os pés de outra pessoa: <span class=\"greek\">περιζωσαμένη</span> <span class=\"greek\">λέντιον</span>).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0217-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λεόπαρδος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λεόπαρδος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Galen: CMG V 4, 1, 1 p. 86, 15; Anecdota Astrol. [ALudwich, Maximi et Ammonis carmina 1877] p. 122, 2; Theognost.: Anecd. Gr. p. 1394; AcPh 94–101 [Aa II/2, 36–39]; 121 [Aa II/2, 50]; Athanasius, Vi. Anton. 9 vol. I 640) leopardo; metaforicamente, soldados violentos <span class=\"greek\">ἐνδεδεμένος</span> (variante textual <span class=\"greek\">δεδεμένος</span>) <span class=\"greek\">δέκα</span> <span class=\"greek\">λεοπάρδοις</span> amarrado a dez «leopardos» IRo 5:1 (o acréscimo de <span class=\"greek\">ὅ</span> <span class=\"greek\">ἐστι</span> <span class=\"greek\">στρατιωτικὸν</span> <span class=\"greek\">τάγμα</span> sugere que a expressão é aqui metafórica; ela é ainda mais apropriada porque Inácio está sendo levado prisioneiro a Roma para combater com feras; mas veja DSaddington, JTS 38, ’87, 411f [uma «cohors» denominada Lepidiana]).—DELG.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0217-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λεπίς, ίδος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λεπίς</span>, <span class=\"greek\">ίδος</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">λέπω</span> «descascar»; uma camada fina que cobre algo, como as «escamas» dos peixes, Hdt. e outros; Michel 833, 11 [279 a.C.]; BGU 544, 8; PGM 4, 258 al.; LXX; TestJob 43:8; Philo; Jos., Ant. 3, 149) «escama».</p><p class=\"entry-text\">① placas achatadas que recobrem a pele de animais marinhos, escamas; sentido coletivo B 10:1 (cp. Lev 11:9ff; Dt 14:9f; TestJob 43:8 <span class=\"greek\">λεπίδας</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">δράκοντος</span>).</p><p class=\"entry-text\">② uma lâmina fina que se desprende, escama, em uma comparação <span class=\"greek\">ἀπέπεσαν</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ὀφθαλμῶν</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">λεπίδες</span> algo semelhante a escamas caiu-lhe dos olhos, isto é, recuperou subitamente a visão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.18\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:18</a>. Quanto à expressão, cf. Galen: CMG V 4, 1, 1 p. 77, 3 <span class=\"greek\">οἷον</span> <span class=\"greek\">λεπὶς</span> <span class=\"greek\">ἀπέπιπτε</span>=«algo semelhante a uma escama caiu» (outros exemplos em Hobart 39). Quanto à figura, cf. Tob 11:12.—DELG s.v. <span class=\"greek\">λέπω</span> A 1. M-M. TW. Spicq.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0217-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λέπρα, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λέπρα</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (veja <span class=\"greek\">λεπρός</span>; Hdt. e outros; Galen: CMG V 4, 2 p. 333, 5; 429, 11; PSI X, 1180, 36 [II d.C.]; LXX, Philo; Jos., Ant. 3, 265, C. Ap. 1, 235; Theoph. Ant. 3, 21 [p. 244, 19]) uma doença cutânea grave, possivelmente incluindo a hanseníase. Os autores médicos gregos incluem diferentes enfermidades da pele sob o termo <span class=\"greek\">λ</span>. Há abundantes indícios de que nem todos os casos designados por <span class=\"hebrew\" dir=\"rtl\">צָרַעַת</span> (cf. Lv 13 e seguintes) e <span class=\"greek\">λέπρα</span> na Bíblia correspondem à verdadeira «hanseníase» causada pelo bacilo de Hansen, conforme conhecida na medicina moderna; de fato, muitos estudiosos (vejam-se Gramberg e Cochrane abaixo) sustentam que a doença de Hansen era desconhecida nos tempos bíblicos ou que era conhecida por nome diferente de «lepra». <span class=\"greek\">λέπρα</span> na LXX e no NT pode por vezes designar aquilo que normalmente se chama hanseníase, mas também são possibilidades prováveis enfermidades cutâneas como psoríase, lúpus, tinha e favo, e, na ausência de dados mais precisos, convém empregar o termo mais geral «doença cutânea grave» <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:12f</a>; PEg2 39 [<span class=\"greek\">ἀ</span>]<span class=\"greek\">π̣έστη</span> <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">λέπ̣</span>[<span class=\"greek\">ρα</span>]=ASyn. 42, 32.—GMünch, Die Zaraath (Lepra) der hebr. Bibel 1893; EMcEwen, Biblical World 38, 1911, 194–202; 255–61; LHuizinga, Leprosy: BiblSacra 83, 1926, 29–46; 202–12; Billerb. IV 1928, 745–63; Handb. d. Haut-u. Geschlechtskrankheiten, ed. JJadassohn, vol. X: Die Lepra 1930; FLendrum, The Name ‘Leprosy’: Amer. Journ. of Tropical Medicine and Hygiene 1, ’52, 999–1008. Série de artigos em BT: KGramberg, 11, ’60, 10–20; JSwellengrebel, 11, ’60, 69–80, com nota de ENida; RCochrane, Biblical Leprosy, 12 ’61, 202f, com menção a uma publicação separada de mesmo título, ’61; DWallington, 12, ’61, 75–79; SBrowne, Leprosy in the Bible, em Medicine and the Bible, ed. BPalmer, ’86, 101–25; MGrmek, Diseases in the Ancient Greek World ’89, 160–61.—ABD IV 277–82 (literatura). TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0217-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λεπράω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λεπράω</span> 1º aoristo <span class=\"greek\">ἐλέπρησα</span> (Hdt., Hippocr. e outros; Num 12:10) sofrer de uma enfermidade cutânea (a associação etimológica com <span class=\"greek\">λεπίς</span> «escama» não deve ser exagerada) <span class=\"greek\">ἐλ</span>[<span class=\"greek\">έπρησα</span>] PEg2 35=ASyn. 42, 31 e 84, 31.—DELG s.v. <span class=\"greek\">λέπω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0217-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λεπρός, ά, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λεπρός</span>, <span class=\"greek\">ά</span>, <span class=\"greek\">όν</span> (veja <span class=\"greek\">λεπίς</span> e <span class=\"greek\">λέπρα</span>; Aristoph., Fgm. 723 K.; Theophr.; Herodas 6, 36 e outros; na descrição de um criminoso procurado PMich IV/1, 223; 1189; 224, 2024; 225, 1751 [todos do século III d.C. e referentes à mesma pessoa]; LXX; Mel., P. 72, 526; Theoph. Ant. 3, 21 [p. 244, 24]; «escamoso») referente à condição de portador de doença cutânea grave, acometido de enfermidade grave da pele (assim em Theophr., CP 2, 6, 4 de pessoas que se tornam «escamoso», com condição semelhante nas plantas; LXX) <span class=\"greek\">λεπροὶ</span> <span class=\"greek\">ἄνδρες</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:12</a>.—Como substantivo, <span class=\"greek\">ὁ</span> <span class=\"greek\">λ</span>., pessoa acometida de doença grave da pele (Philo, Leg. All. 3, 7; Jos., Ant. 3, 264, C. Ap. 1, 278) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:2</a>; 10:8; 11:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:40</a> (CMasson, La péricope du lépreux [<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:40</a>–45]: RTP n.s. 23, ’39, 287–95); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:27</a>; 7:22 (sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:5</a> e <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.22\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:22</a>, veja <span class=\"greek\">κωφός</span> 2); PEg2 32=ASyn. 42, 30. Como cognome de Simão de Betânia (cp. Sb 7638, 4f [257 b.c.] <span class=\"greek\">τὴν</span> <span class=\"greek\">Νικάνορος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ποδαγρικοῦ</span> <span class=\"greek\">οἰκίαν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:6</a> (<span class=\"greek\">λεπρωσοῦ</span>; D, segundo o latim: leprosi) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 14:3</a>.—DELG s.v. <span class=\"greek\">λέπω</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0217-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λεπτός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λεπτός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (Hom.+; SIG 567, 6; pap, LXX, TestSol 11:7; JosAs 10:13; Philo; Jos., Bell. 2, 154; SibOr 1, 361; superlativo <span class=\"greek\">λεπτότατος</span> Just., D. 46, 5).</p><p class=\"entry-text\">① referente ao que tem volume relativamente reduzido, pequeno, fino, leve <span class=\"greek\">ὄστρακον</span> <span class=\"greek\">λ</span>. Hs 9, 10, 1; <span class=\"greek\">θηρία</span> <span class=\"greek\">λ</span>. animais diminutos ApcPt Fgm. 2 p. 12, 27.</p><p class=\"entry-text\">② <span class=\"greek\">τὸ</span> <span class=\"greek\">λ</span>. (subentenda-se <span class=\"greek\">νόμισμα</span>, com Artem. 2, 58; Pollux 9, 92 ou <span class=\"greek\">κέρμα</span>, com Alciphron 1, 9, 1) pequena moeda de cobre, equivalente a 1/128 de denário, de valor entre um penny e um mill, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.59\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:59</a>; 21:2. (cp. OGI 484, 35; SIG 1109, 80; 98f )—Veja <span class=\"greek\">ἀργύριον</span> 2c.—Schürer II 66; Kl. Pauly III 582; B. 889. DELG s.v. <span class=\"greek\">λέπω</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0217-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λευί, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Λευί</span>, <span class=\"greek\">ὁ</span> (<span class=\"hebrew\" dir=\"rtl\">לֵוִי</span>) indeclinável (B-D-F §53, 1) e <span class=\"greek\">Λευίς</span>, genitivo <span class=\"greek\">Λευί</span>, acusativo <span class=\"greek\">Λευίν</span> (B-D-F §55, 1e; W-S. §10, 5; Wuthnow 67; Mlt-H. 146 <span class=\"greek\">Λευείς</span>; as formas e grafias dos manuscritos e das edições variam: <span class=\"greek\">Λευί̈</span>-, <span class=\"greek\">Λευεί</span>-) Levi (LXX; Test12Patr [<span class=\"greek\">Λευί</span>; variantes textuais <span class=\"greek\">Λευίς</span>, <span class=\"greek\">Λευίν</span>]; JosAs [<span class=\"greek\">Λευίς</span>; variante textual <span class=\"greek\">Λευί</span>]; EpArist 48; Philo, Joseph.).</p><p class=\"entry-text\">① filho de Jacó <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:9</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">υἱοὶ</span> <span class=\"greek\">Λευί</span> vs. 5; <span class=\"greek\">φυλὴ</span> <span class=\"greek\">Λ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:7</a>.</p><p class=\"entry-text\">② filho de Melqui, na genealogia de Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:24</a>.</p><p class=\"entry-text\">③ filho de Simeão, na genealogia de Jesus vs. 29.</p><p class=\"entry-text\">④ discípulo de Jesus, chamado por ele quando estava na repartição de cobrança de tributos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:27</a>, 29. Segundo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:14</a>, esse discípulo era filho de Alfeu (s. <span class=\"greek\">Ἁλφαῖος</span> 1). GPt 14:60 também menciona um <span class=\"greek\">Λευὶς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἁλφαίου</span> como discípulo de Jesus. GMary 463, 18; 31. Sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:9</a>, veja <span class=\"greek\">Μαθθαῖος</span>.</p><p class=\"entry-text\">⑤ nome de um sumo sacerdote, parcialmente reconstituído <span class=\"greek\">Λευ</span>[<span class=\"greek\">είς</span>?] Ox 840, 10.—Pauly-W. XII 2207f; BHHW III 1076. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0217-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λευίτης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Λευίτης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (manuscritos e edições também registram <span class=\"greek\">Λευί̈</span>-, <span class=\"greek\">Λευειτ</span>-. LXX, Philo, Joseph.; Plut., Mor. 671e) levita, membro da tribo de Levi, especialmente aquele que não pertencia à família de Arão e tinha por incumbência os serviços mais modestos ligados ao ritual do templo. Com <span class=\"greek\">ἱερεύς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:32</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.19\" target=\"_blank\" rel=\"noopener noreferrer\">J 1:19</a>; 1 Cl 32:2; 40:5. Quanto a José Barnabé <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.36\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:36</a>.—JEmerton, VetusT 12, ’62, 129–38 (Deut.); AGunneweg, Leviten u. Priester, ’65.—TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0217-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Λευιτικός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Λευιτικός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (quanto à grafia, veja <span class=\"greek\">Λευίτης</span>. título de Lev; Philo; Just., D. 16, 1 <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Λ</span>.; Mel., HE 4, 26, 14 <span class=\"greek\">Λευιτικόν</span>) levítico <span class=\"greek\">Λ</span>. <span class=\"greek\">ἱερωσύνη</span> o sacerdócio levítico (isto é, do Antigo Testamento) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:11</a>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0217-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">λευκαίνω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">λευκαίνω</span> futuro <span class=\"greek\">λευκανῶ</span> Is 1:18; 1º aoristo <span class=\"greek\">ἐλεύκανα</span> (B-D-F §72; Mlt-H. 214f), infinitivo <span class=\"greek\">λευκᾶναι</span>. Na voz passiva: futuro <span class=\"greek\">λευκανθήσομαι</span> Ps 50:9; particípio perfeito, feminino acusativo <span class=\"greek\">λελευκασμένην</span> TestSol (veja <span class=\"greek\">λευκός</span>; Hom. e outros; Apollod. [II a.C.]: 244 Fgm. 107c Jac.; Sb 6754, 18; LXX; TestSol C prol. 1; Philo, Leg. All. 2, 43) tornar branco; de roupas embranquecidas por um pisoeiro (Aesop, Fab. 29 P.=59 H.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:3</a>. Em linguagem figurada, tornar brancos pecados vermelhos como sangue 1 Cl 8:4 (Is 1:18); cp. 18:7 (Ps 50:9). Em figura apocalíptica, a respeito dos mártires: <span class=\"greek\">ἐλεύκαναν</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">στολὰς</span> <span class=\"greek\">αὐτῶν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">αἵματι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἀρνίου</span> tornaram brancas suas vestes no sangue do Cordeiro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:14</a>.—DELG s.v. 1 <span class=\"greek\">λευκός</span>. TW.</p></section></article>"};
